1	/**
2	 * Minimal custom Function HTTP server for Vercel container images.
3	 * Listens on PORT (default 80 per Vercel container runtime docs).
4	 *
5	 * Public route prefix on the deployment: /oci (see root vercel.json services + rewrites).
6	 * Vercel may pass the original path (/oci/...) even after service routing, so we strip
7	 * that prefix before matching handlers. Service-level request.path transforms do the same.
8	 *
9	 * @see https://vercel.com/docs/functions/container-images
10	 * @see https://vercel.com/docs/services/routing
11	 */
12	
13	import http from "node:http";
14	import { toServicePath } from "./path.mjs";
15	
16	const port = Number(process.env.PORT || 80);
17	const host = process.env.HOST || "0.0.0.0";
18	
19	const server = http.createServer((req, res) => {
20	  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
21	  const path = toServicePath(url.pathname);
22	
23	  if (req.method === "GET" && (path === "/health" || path === "/healthz")) {
24	    res.writeHead(200, { "content-type": "application/json; charset=utf-8" });
25	    res.end(
26	      JSON.stringify({
27	        ok: true,
28	        service: "new-dobeu-net-oci",
29	        path,
30	        publicPath: url.pathname,
31	      }),
32	    );
33	    return;
34	  }
35	
36	  if (req.method === "GET" && path === "/") {
37	    res.writeHead(200, { "content-type": "application/json; charset=utf-8" });
38	    res.end(
39	      JSON.stringify({
40	        ok: true,
41	        service: "new-dobeu-net-oci",
42	        message: "Custom Vercel Function container is running",
43	        path,
44	        publicPath: url.pathname,
45	        method: req.method,
46	      }),
47	    );
48	    return;
49	  }
50	
51	  res.writeHead(404, { "content-type": "application/json; charset=utf-8" });
52	  res.end(
53	    JSON.stringify({
54	      ok: false,
55	      error: "not_found",
56	      path,
57	      publicPath: url.pathname,
58	    }),
59	  );
60	});
61	
62	function shutdown(signal) {
63	  console.log(`[oci] received ${signal}, shutting down`);
64	  server.close(() => {
65	    process.exit(0);
66	  });
67	  // Force exit if graceful close hangs past Vercel's SIGTERM window.
68	  setTimeout(() => process.exit(1), 25_000).unref();
69	}
70	
71	process.on("SIGTERM", () => shutdown("SIGTERM"));
72	process.on("SIGINT", () => shutdown("SIGINT"));
73	
74	server.listen(port, host, () => {
75	  console.log(`[oci] listening on http://${host}:${port}`);
76	});
