1	/** Public URL prefix for the OCI container service (vercel.json rewrites). */
2	export const PUBLIC_PREFIX = "/oci";
3	
4	/**
5	 * Map the public URL path to the path container handlers understand.
6	 * /oci        -> /
7	 * /oci/       -> /
8	 * /oci/health -> /health
9	 * /health     -> /health (local docker run / path-stripped transforms)
10	 */
11	export function toServicePath(pathname) {
12	  if (pathname === PUBLIC_PREFIX || pathname === `${PUBLIC_PREFIX}/`) {
13	    return "/";
14	  }
15	  if (pathname.startsWith(`${PUBLIC_PREFIX}/`)) {
16	    const rest = pathname.slice(PUBLIC_PREFIX.length);
17	    return rest.startsWith("/") ? rest : `/${rest}`;
18	  }
19	  return pathname;
20	}
